// js/ui/hudButtons.js
import { lsSetItem, lsGetItem } from "../main.js";
import { openHelpOverlay } from "./helpOverlay.js";
import { openMapOverlay, ensureMapOverlay } from "./mapOverlay.js";
import { openShop } from "./shopOverlay.js";
import { openSasOverlay } from "./sas/sasOverlay.js";
import { ensureMerchantOverlay } from "./merchantTabs/dlgTab.js";
import { getActiveSlot, hasModifiedSave } from "../util/storage.js";
import { shouldSkipGhostTap } from "../util/ghostTapGuard.js";
const BASE_KEYS = {
    SHOP: "ccc:unlock:shop",
    SHOP_UC: "ccc:unlock:shop:uc",
    MAP: "ccc:unlock:map",
};

function slotKey(base) {
    const slot = getActiveSlot();
    return slot == null ? base : `${base}:${slot}`;
}

function isUnlocked(base) {
    const key = slotKey(base);
    const slotRaw = lsGetItem(key);
    if (slotRaw != null) return slotRaw === "1";
    return lsGetItem(base) === "1";
}

export function isShopUnlocked() {
    ensureUnlockDefaults();
    return isUnlocked(BASE_KEYS.SHOP);
}

export function isShopUcUnlocked() {
    ensureUnlockDefaults();
    return isUnlocked(BASE_KEYS.SHOP_UC);
}

export function isMapUnlocked() {
    ensureUnlockDefaults();
    return isUnlocked(BASE_KEYS.MAP);
}

function setUnlocked(base, v) {
    const val = v ? "1" : "0";
    const key = slotKey(base);
    lsSetItem(key, val);
    if (key !== base && lsGetItem(base) != null) {
        lsSetItem(base, val);
    }
    try {
        window.dispatchEvent(
            new CustomEvent("unlock:change", {
                detail: { key: base, slot: getActiveSlot() },
            }),
        );
    } catch {}
}

function ensureUnlockDefaults() {
    if (getActiveSlot() == null) return;
    for (const key of Object.values(BASE_KEYS)) {
        const sk = slotKey(key);
        const hasSlot = lsGetItem(sk) != null;
        if (!hasSlot) lsSetItem(sk, "0");
    }
}

function setButtonVisible(key, visible) {
    const el = document.querySelector(`.hud-bottom [data-btn="${key}"]`);
    if (el) el.hidden = !visible;
}

function updateShopButtonTamperState() {
    const btn = document.querySelector('.hud-bottom [data-btn="shop"]');
    if (!btn) return;
    btn.classList.toggle("btn-shop--modified", hasModifiedSave());
}

function phonePortrait() {
    const isCoarse = window.matchMedia("(pointer: coarse)").matches;
    const isPortrait = window.innerHeight >= window.innerWidth;
    return isCoarse && isPortrait;
}

let listenersBound = false;
let actionsBound = false;
// ===============================
// HUD layout
// ===============================
export function applyHudLayout() {
    const hud = document.querySelector(".hud-bottom");
    if (!hud) return;
    const mapBtn = hud.querySelector('[data-btn="map"]');
    const isMapVisible = !!(mapBtn && !mapBtn.hidden);
    const isPhonePortrait = phonePortrait();
    const baseOrder = ["help", "shop", "stats", "map"];
    const mobileMapOrder = ["help", "stats", "shop", "map"];
    const desiredOrder = isPhonePortrait && isMapVisible ? mobileMapOrder : baseOrder;
    const desiredNodes = desiredOrder.map((key) => hud.querySelector(`.game-btn[data-btn="${key}"]`)).filter(Boolean);
    const remainingNodes = [...hud.children].filter((el) => !desiredNodes.includes(el));
    const finalOrder = [...desiredNodes, ...remainingNodes];
    const needsReorder = finalOrder.length && finalOrder.some((el, idx) => hud.children[idx] !== el);
    if (needsReorder) {
        const frag = document.createDocumentFragment();
        finalOrder.forEach((node) => frag.appendChild(node));
        hud.appendChild(frag);
    }

    const all = [...hud.querySelectorAll(".game-btn[data-btn]")];
    const visible = all.filter((el) => !el.hidden);
    // Reset previous hints
    hud.classList.remove("is-2", "is-3", "is-4");
    visible.forEach((el) => {
        el.style.gridColumn = "";
        el.style.gridRow = "";
        el.classList.remove("span-2");
        el.style.order = "";
    });
    hud.style.gridTemplateColumns = "";
    hud.style.justifyContent = "";
    hud.classList.add(`is-${visible.length}`);
    // Desktop centering
    if (!isPhonePortrait) {
        const cs = getComputedStyle(hud);
        const gap = parseFloat(cs.columnGap || cs.gap || "0") || 0;
        const cw = hud.clientWidth;
        const per = Math.max(180, Math.floor((cw - 3 * gap) / 4));
        if (visible.length === 2) {
            hud.style.gridTemplateColumns = `repeat(2, ${per}px)`;
            hud.style.justifyContent = "center";
            return;
        }
        if (visible.length === 3) {
            hud.style.gridTemplateColumns = `repeat(3, ${per}px)`;
            hud.style.justifyContent = "center";
            return;
        }
    }
    // Mobile portrait (2×2): Help & Stats top; Shop full width bottom
    if (isPhonePortrait && visible.length === 3) {
        const help = hud.querySelector('[data-btn="help"]:not([hidden])');
        const stats = hud.querySelector('[data-btn="stats"]:not([hidden])');
        const shop = hud.querySelector('[data-btn="shop"]:not([hidden])');
        if (help && stats && shop) {
            help.style.gridColumn = "1";
            help.style.gridRow = "1";
            stats.style.gridColumn = "2";
            stats.style.gridRow = "1";
            shop.style.gridColumn = "1 / -1";
            shop.style.gridRow = "2";
        }
    }
}

export function initHudButtons() {
    ensureUnlockDefaults();
    // Always-on buttons
    setButtonVisible("help", true);
    setButtonVisible("stats", true);
    updateShopButtonTamperState();
    refreshButtonVisibility();
    // Preload Merchant Overlay (Delve screen) during idle time
    // This is a performance optimization to ensure the heavy DOM is ready
    // before the user clicks the "Delve" button in the shop.
    if (typeof window.requestIdleCallback === "function") {
        window.requestIdleCallback(
            () => {
                ensureMerchantOverlay();
                ensureMapOverlay();
            },
            { timeout: 5000 },
        );
    } else {
        setTimeout(() => {
            ensureMerchantOverlay();
            ensureMapOverlay();
        }, 100);
    }
    if (!listenersBound) {
        listenersBound = true;
        window.addEventListener("resize", applyHudLayout);
        window.addEventListener("orientationchange", applyHudLayout);
        window.addEventListener("saveSlot:change", () => {
            updateShopButtonTamperState();
            refreshButtonVisibility();
        });
        window.addEventListener("saveSlot:modified", (event) => {
            const active = getActiveSlot();
            const slot = event?.detail?.slot;
            if (slot != null && active != null && slot !== active) return;
            updateShopButtonTamperState();
        });
    }
    // Bind actions once (click → open shop)
    if (!actionsBound) {
        actionsBound = true;
        const hud = document.querySelector(".hud-bottom");
        if (hud) {
            const activate = (btn) => {
                if (!btn) return;
                const key = btn.getAttribute("data-btn");
                if (key === "shop") {
                    openShop();
                } else if (key === "stats") {
                    openSasOverlay();
                } else if (key === "help") {
                    openHelpOverlay();
                } else if (key === "map") {
                    openMapOverlay();
                }
                // future: help/settings/map can import their own modules, too
            };

            const onClick = (e) => {
                const btn = e.target.closest(".game-btn");
                if (!btn) return;
                const key = btn.getAttribute("data-btn");
                if (key !== "shop" && key !== "stats" && key !== "help" && key !== "map") return;
                if (e.isTrusted && shouldSkipGhostTap(btn)) return;
                // markGhostTapTarget removed - global handler manages clicks
                activate(btn);
            };
            hud.addEventListener("click", onClick, { passive: true });
        }
    }
}
// Convenience helpers (write both keys)
export function unlockShop() {
    setUnlocked(BASE_KEYS.SHOP, true);
    refreshButtonVisibility();
}

export function unlockShopUc() {
    setUnlocked(BASE_KEYS.SHOP_UC, true);
    refreshButtonVisibility();
}

export function unlockMap() {
    setUnlocked(BASE_KEYS.MAP, true);
    setButtonVisible("map", true);
    applyHudLayout();
}

export function lockShop() {
    setUnlocked(BASE_KEYS.SHOP, false);
    refreshButtonVisibility();
}

export function lockShopUc() {
    setUnlocked(BASE_KEYS.SHOP_UC, false);
    refreshButtonVisibility();
}

export function lockMap() {
    setUnlocked(BASE_KEYS.MAP, false);
    setButtonVisible("map", false);
    applyHudLayout();
}

export function refreshButtonVisibility() {
    const currentArea = window.currentArea; // Depends on global, fallback handled if necessary
    // By default, areas allow shop if `isShopUnlocked` is true. But for UC we require `isShopUcUnlocked`.
    let shopVisible = false;
    if (currentArea === 2) {
        // 2 = AREAS.UNDERWATER_CAVERN
        shopVisible = isShopUcUnlocked();
    } else {
        shopVisible = isShopUnlocked();
    }
    setButtonVisible("shop", shopVisible);
    setButtonVisible("map", isUnlocked(BASE_KEYS.MAP));
    applyHudLayout();
}
