export function getActiveSlot() {
    if (_activeSlotCache !== undefined) return _activeSlotCache;
    const raw = lsGetItem(KEYS.SAVE_SLOT);
    const n = parseInt(raw, 10);
    const val = Number.isFinite(n) && n > 0 ? n : null;
    _activeSlotCache = val;
    return val;
}

export function setActiveSlot(n) {
    const v = Math.max(1, parseInt(n, 10) || 1);
    _activeSlotCache = v;
    lsSetItem(KEYS.SAVE_SLOT, String(v));
    try {
        lsSetItem(`ccc:instanceId:${v}`, _myInstanceId);
    } catch {}
    try {
        window.dispatchEvent(new CustomEvent("saveSlot:change", { detail: { slot: v } }));
    } catch {}
}

export function clearActiveSlot() {
    const currentSlot = getActiveSlot();
    // Only update lastSaveTime if we've actually been in a game session.
    // Otherwise, on page load, this will instantly overwrite the frozen
    // lastSaveTime from the previous session with the current time, erasing offline progress.
    if (currentSlot != null && hasEnteredGameSession) {
        try {
            memoryLastSaveTime = Date.now();
            lsSetItem(getLastSaveTimeKey(currentSlot), String(memoryLastSaveTime));
        } catch (e) {
            console.error(e);
        }
    }
    hasEnteredGameSession = false;
    memoryLastSaveTime = 0;
    _activeSlotCache = null;
    lsRemoveItem(KEYS.SAVE_SLOT);
    try {
        window.dispatchEvent(new CustomEvent("saveSlot:change", { detail: { slot: null } }));
    } catch {}
}
